<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/layout.php';
$user=require_auth();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$q=$pdo->prepare('INSERT INTO visits (os_number,visit_date,client_name,seller_user_id,visit_type,contact_name,phone,sector,equipment,summary,opportunity_text,source,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,"manual",?)');$q->execute([trim((string)($_POST['os_number']??''))?:null,(string)($_POST['visit_date']??date('Y-m-d')),trim((string)($_POST['client_name']??'')),($_POST['seller_user_id']??'')!==''?(int)$_POST['seller_user_id']:null,in_array($_POST['visit_type']??'visita',['visita','prospeccao'],true)?$_POST['visit_type']:'visita',trim((string)($_POST['contact_name']??'')),trim((string)($_POST['phone']??'')),trim((string)($_POST['sector']??'')),trim((string)($_POST['equipment']??'')),trim((string)($_POST['summary']??'')),trim((string)($_POST['opportunity_text']??'')),(int)$user['id']]);$id=(int)$pdo->lastInsertId();audit($pdo,(int)$user['id'],'create','visit',$id);flash('success','Visita registrada.');}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('visitas.php');}
$users=$pdo->query("SELECT id,name FROM users WHERE active=1 ORDER BY name")->fetchAll();$rows=$pdo->query("SELECT v.*,u.name seller_name FROM visits v LEFT JOIN users u ON u.id=v.seller_user_id ORDER BY visit_date DESC,id DESC LIMIT 300")->fetchAll();
page_header('Visitas','visitas');
?>
<div class="page-actions"><div><span class="eyebrow">CAMPO</span><h2>Registrar visita</h2><p>Estrutura pronta para receber leitura assistida por IA dos relatórios de visita na próxima etapa.</p></div></div>
<div class="card"><form method="post" class="form-grid"><?= csrf_field() ?><label><span>OS / referência</span><input name="os_number"></label><label><span>Data</span><input type="date" name="visit_date" value="<?= date('Y-m-d') ?>" required></label><label class="span-2"><span>Cliente</span><input name="client_name" required></label><label><span>Responsável DNB</span><select name="seller_user_id"><option value="">—</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?></option><?php endforeach; ?></select></label><label><span>Tipo</span><select name="visit_type"><option value="visita">Visita</option><option value="prospeccao">Prospecção</option></select></label><label><span>Contato</span><input name="contact_name"></label><label><span>Telefone</span><input name="phone"></label><label><span>Setor</span><input name="sector"></label><label><span>Equipamentos citados</span><input name="equipment"></label><label class="span-2"><span>Resumo</span><textarea name="summary" rows="3"></textarea></label><label class="span-2"><span>Oportunidades identificadas</span><textarea name="opportunity_text" rows="4"></textarea></label><div class="span-2 form-actions"><button class="btn btn-primary" type="submit">Salvar visita</button></div></form></div>
<div class="card"><div class="card-title"><div><span class="tag">HISTÓRICO</span><h3>Visitas (<?= count($rows) ?>)</h3></div></div><?php if(!$rows): ?><?php empty_state('Nenhuma visita registrada','Os registros reais de campo aparecerão aqui.'); ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>OS</th><th>Cliente</th><th>Responsável</th><th>Tipo</th><th>Contato</th><th>Oportunidade</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= e($row['visit_date']) ?></td><td class="mono"><?= e($row['os_number']?:'—') ?></td><td><strong><?= e($row['client_name']) ?></strong></td><td><?= e($row['seller_name']?:'—') ?></td><td><?= e($row['visit_type']==='prospeccao'?'Prospecção':'Visita') ?></td><td><?= e($row['contact_name']?:'—') ?><small><?= e($row['phone']?:'') ?></small></td><td><?= e($row['opportunity_text']?:'—') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div>
<?php page_footer(); ?>
